 page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8000/');page.wait_for_function('window.__slope',timeout=180000);page.get_by_role('button',name='開始探索',exact=True).click(timeout=90000)
